#include "bmm/scanner.hpp"
#include "bmm/language_model.hpp"
#include "bmm/sentence.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <sqlite3.h>
using namespace bmm;
#define CHECK(x) do{if(!(x))throw std::runtime_error("CHECK failed: " #x);}while(0)
int main(){
  LocalGenerator a(42,256),b(42,256),c(43,256);auto p=a.generate(9);CHECK(p.text==b.generate(9).text);CHECK(p.text!=c.generate(9).text);CHECK(p.text.size()==256);CHECK(p.address=="local:42:9");for(char x:p.text)CHECK(std::string("abcdefghijklmnopqrstuvwxyz ,.").find(x)!=std::string::npos);
  Analyzer az({"the","old","man","hello"});auto h=az.analyze("x the old man. hello! other","test");CHECK(h.size()>=6);CHECK(h[0].text=="the");for(auto&f:h)CHECK(f.text!="the"||f.start==2);
  Grammar grammar;CHECK(grammar.evaluate(NGramLanguageModel::tokenize("the dog sees a cat")).accepted);CHECK(grammar.evaluate(NGramLanguageModel::tokenize("she is happy")).accepted);CHECK(grammar.evaluate(NGramLanguageModel::tokenize("the man walks in the garden")).accepted);CHECK(!grammar.evaluate(NGramLanguageModel::tokenize("the sings bird")).accepted);CHECK(!grammar.evaluate(NGramLanguageModel::tokenize("birds flies")).accepted);CHECK(!grammar.evaluate(NGramLanguageModel::tokenize("she are happy")).accepted);
  auto model=NGramLanguageModel::train("data/evaluation/positive_train.txt");auto good=model.score("the dog sees a cat");CHECK(good.trained);CHECK(good.tokens==5);auto model_path=std::filesystem::temp_directory_path()/"bmm-model.ngram";model.save(model_path.string());auto loaded=NGramLanguageModel::load(model_path.string());CHECK(loaded.score("the dog sees a cat").normalized==good.normalized);
  SentenceScorer scorer(grammar,loaded);auto assessed=scorer.score("the dog sees a cat");CHECK(assessed.classification=="GRAMMATICAL_SENTENCE");CHECK(scorer.score("the sings bird").classification=="SENTENCE_CANDIDATE");
  Analyzer saz({"the","dog","sees","a","cat"},SentenceOptions{},scorer);auto sh=saz.analyze("xx. the dog sees a cat. yy","sentence-test");bool found=false;for(auto&f:sh)if(f.classification=="GRAMMATICAL_SENTENCE"){found=true;CHECK(f.start==4);CHECK(f.end==22);CHECK(f.word_count==5);}CHECK(found);
  auto dir=std::filesystem::temp_directory_path()/"bmm-tests";std::filesystem::create_directories(dir);auto dbp=dir/"test.db";std::filesystem::remove(dbp);{Storage db(dbp.string());auto id=db.create_experiment("local",7,"{}");Scanner s;auto st=s.run(LocalGenerator(7,128),az,db,id,{1000,0,4,50,true});CHECK(st.pages==1000);auto e=db.experiment(id);CHECK(e.pages_scanned==1000);CHECK(e.status=="completed");auto out=dir/"out.json";db.export_results(id,"json",out.string());CHECK(std::filesystem::exists(out));std::ifstream f(out);char ch{};f>>ch;CHECK(ch=='[');}
  auto oldp=dir/"old-v1.db";std::filesystem::remove(oldp);sqlite3* raw=nullptr;CHECK(sqlite3_open(oldp.string().c_str(),&raw)==SQLITE_OK);const char* oldsql="CREATE TABLE schema_version(version INTEGER);INSERT INTO schema_version VALUES(1);CREATE TABLE experiments(id INTEGER PRIMARY KEY,backend TEXT,seed INTEGER,configuration TEXT,generator_version TEXT DEFAULT 'v1',started_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,status TEXT,pages_scanned INTEGER DEFAULT 0,elapsed_seconds REAL DEFAULT 0);CREATE TABLE findings(id INTEGER PRIMARY KEY,experiment_id INTEGER,page_address TEXT,start_offset INTEGER,end_offset INTEGER,extracted_text TEXT,lexical_score REAL,language_score REAL,detection_method TEXT,discovered_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE checkpoints(experiment_id INTEGER PRIMARY KEY,last_completed_work_unit INTEGER,updated_at TEXT);";CHECK(sqlite3_exec(raw,oldsql,nullptr,nullptr,nullptr)==SQLITE_OK);sqlite3_close(raw);{Storage migrated(oldp.string());auto id=migrated.create_experiment("local",1,"{}");auto sentence_findings=saz.analyze("the dog sees a cat","migration-page");migrated.save_batch(id,sentence_findings);auto rows=migrated.findings(id,100);bool sentence_row=false;for(auto&f:rows)if(f.classification=="GRAMMATICAL_SENTENCE")sentence_row=true;CHECK(sentence_row);auto out=dir/"sentence.json";migrated.export_results(id,"json",out.string());std::ifstream in(out);std::string json((std::istreambuf_iterator<char>(in)),{});CHECK(json.find("grammar_score")!=std::string::npos);CHECK(json.find("GRAMMATICAL_SENTENCE")!=std::string::npos);}
  std::cout<<"All tests passed\n";
}
